function isValid(s) {
  var stack = [];
  var pairs = { ")": "(", "]": "[", "}": "{" };
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    if (c === "(" || c === "[" || c === "{") {
      stack.push(c);
    } else if (stack.pop() !== pairs[c]) {
      return false;
    }
  }
  return stack.length === 0;
}

